-- 220: The full table of contents of the Thueringen Lehrplan Biologie Gymnasium 2026 (Erprobungsfassung) in the structure overview.
--
-- Read on 2026-11-02 from the PDF a person had downloaded from the school portal. The portal's robots.txt forbids automated fetching, so no
-- program fetched it. The original stays in a private folder outside every repository. Found by comparing the table of contents with the pilot
-- of migration 216:
-- 1. All 7 Lernbereiche of grades 7 to 10 were already in the pilot (pages 19 to 31 match). One heading differed: the Lehrplan prints
--    'Stoff- und Energiewechselprozesse von gruenen Pflanzen und Pilzen', the pilot had EvoMentor's order 'von Pilzen und gruenen Pflanzen'.
-- 2. Not in the pilot: the Einfuehrungsphase (4 Lernbereiche, pages 33 to 41) and the Qualifikationsphase of the Oberstufe (4 Inhaltsbereiche,
--    6 Lernbereiche, pages 49 to 65). They are added as headings with page numbers only: no summaries yet, no EvoMentor goals.
-- Every node is an LLM synthesized draft awaiting review (review_status ai-draft) at the summary-only tier. Running this twice changes nothing.
-- Generated by scripts/generate_bio_toc_migration.py.
SET search_path = public, extensions;

UPDATE curriculum_repository_structure_nodes n
SET label_de = 'Stoff- und Energiewechselprozesse von grünen Pflanzen und Pilzen', updated_at = now()
WHERE n.project_id = (SELECT id FROM projects WHERE slug = 'thuringia-curriculum-repository')
  AND n.node_key LIKE 'DE-TH/biologie-gymnasium-2026/9/%' AND n.level = 'topic' AND n.label_de = 'Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen';

UPDATE curriculum_repository_structure_nodes n
SET facts = n.facts || jsonb_build_object('coverage_de', 'Alle Lernbereiche der Klassenstufen 7 bis 10 und der Oberstufe stehen im Inhaltsverzeichnis. Unterthemen und Lernziele gibt es nur zu den Themen, für die EvoMentor Thüringen Lernziele hat.'::text, 'coverage_en', 'Every Lernbereich of grades 7 to 10 and of the upper secondary level is listed. Subtopics and goals exist only for topics that EvoMentor Thüringen has goals for.'::text), updated_at = now()
WHERE n.project_id = (SELECT id FROM projects WHERE slug = 'thuringia-curriculum-repository') AND n.node_key = 'DE-TH/biologie-gymnasium-2026';

INSERT INTO curriculum_repository_structure_nodes (project_id, node_key, parent_id, level, subject, school_type, grade_band, sort_order, label_de, label_en, source_pages, facts, access_tier, review_status, origin)
SELECT p.id, v.node_key, parent.id, v.level, 'biologie', 'Gymnasium', v.grade_band, v.sort_order, v.label_de, v.label_en, v.source_pages, v.facts::jsonb, 'summary-only', 'ai-draft', 'lehrplan-toc-2026-11-02'
FROM (VALUES
  ('DE-TH/biologie-gymnasium-2026/einfuehrungsphase', 'DE-TH/biologie-gymnasium-2026', 'grade_band', '11', 'Einführungsphase (mit Realschulabschluss)', 'Introductory phase (with Realschulabschluss)', NULL, '{"section": "3"}', 11),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase', 'DE-TH/biologie-gymnasium-2026', 'grade_band', '11/12', 'Qualifikationsphase der gymnasialen Oberstufe', 'Qualification phase of the upper secondary level', NULL, '{"section": "4"}', 12)
) AS v(node_key, parent_key, level, grade_band, label_de, label_en, source_pages, facts, sort_order)
JOIN projects p ON p.slug = 'thuringia-curriculum-repository'
JOIN curriculum_repository_structure_nodes parent ON parent.project_id = p.id AND parent.node_key = v.parent_key
ON CONFLICT (project_id, node_key) DO NOTHING;

INSERT INTO curriculum_repository_structure_nodes (project_id, node_key, parent_id, level, subject, school_type, grade_band, sort_order, label_de, label_en, source_pages, facts, access_tier, review_status, origin)
SELECT p.id, v.node_key, parent.id, v.level, 'biologie', 'Gymnasium', v.grade_band, v.sort_order, v.label_de, v.label_en, v.source_pages, v.facts::jsonb, 'summary-only', 'ai-draft', 'lehrplan-toc-2026-11-02'
FROM (VALUES
  ('DE-TH/biologie-gymnasium-2026/einfuehrungsphase/gruene-pflanzen-und-pilze', 'DE-TH/biologie-gymnasium-2026/einfuehrungsphase', 'topic', '11', 'Stoff- und Energiewechselprozesse von grünen Pflanzen und Pilzen', 'Matter and energy processes in green plants and fungi', 'p. 33', '{"section": "3.1.1"}', 1),
  ('DE-TH/biologie-gymnasium-2026/einfuehrungsphase/oekologie', 'DE-TH/biologie-gymnasium-2026/einfuehrungsphase', 'topic', '11', 'Ökologie', 'Ecology', 'p. 36', '{"section": "3.1.2"}', 2),
  ('DE-TH/biologie-gymnasium-2026/einfuehrungsphase/genetik', 'DE-TH/biologie-gymnasium-2026/einfuehrungsphase', 'topic', '11', 'Genetik', 'Genetics', 'p. 37', '{"section": "3.1.3"}', 3),
  ('DE-TH/biologie-gymnasium-2026/einfuehrungsphase/evolution', 'DE-TH/biologie-gymnasium-2026/einfuehrungsphase', 'topic', '11', 'Evolution', 'Evolution', 'p. 41', '{"section": "3.1.4"}', 4),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase', 'topic', '11/12', 'Inhaltsbereich Leben und Energie', 'Content area: Life and energy', 'p. 49', '{"section": "4.1.1"}', 1),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/informationsverarbeitung', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase', 'topic', '11/12', 'Inhaltsbereich Informationsverarbeitung in Lebewesen', 'Content area: Information processing in organisms', 'p. 55', '{"section": "4.1.2"}', 2),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/lebewesen-in-ihrer-umwelt', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase', 'topic', '11/12', 'Inhaltsbereich Lebewesen in ihrer Umwelt', 'Content area: Organisms in their environment', 'p. 58', '{"section": "4.1.3"}', 3),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase', 'topic', '11/12', 'Inhaltsbereich Vielfalt des Lebens', 'Content area: Diversity of life', 'p. 61', '{"section": "4.1.4"}', 4)
) AS v(node_key, parent_key, level, grade_band, label_de, label_en, source_pages, facts, sort_order)
JOIN projects p ON p.slug = 'thuringia-curriculum-repository'
JOIN curriculum_repository_structure_nodes parent ON parent.project_id = p.id AND parent.node_key = v.parent_key
ON CONFLICT (project_id, node_key) DO NOTHING;

INSERT INTO curriculum_repository_structure_nodes (project_id, node_key, parent_id, level, subject, school_type, grade_band, sort_order, label_de, label_en, source_pages, facts, access_tier, review_status, origin)
SELECT p.id, v.node_key, parent.id, v.level, 'biologie', 'Gymnasium', v.grade_band, v.sort_order, v.label_de, v.label_en, v.source_pages, v.facts::jsonb, 'summary-only', 'ai-draft', 'lehrplan-toc-2026-11-02'
FROM (VALUES
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie/cytologie', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie', 'subtopic', '11/12', 'Grundlagen der Cytologie', 'Basics of cytology', 'p. 49', '{"section": "4.1.1.1"}', 1),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie/enzymatik', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie', 'subtopic', '11/12', 'Enzymatik', 'Enzymology', 'p. 50', '{"section": "4.1.1.2"}', 2),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie/stoffwechsel', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/leben-und-energie', 'subtopic', '11/12', 'Aufbauender und abbauender Stoffwechsel', 'Anabolic and catabolic metabolism', 'p. 52', '{"section": "4.1.1.3"}', 3),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens/molekulargenetik', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens', 'subtopic', '11/12', 'Molekulargenetische Grundlagen des Lebens', 'Molecular genetic basis of life', 'p. 61', '{"section": "4.1.4.1"}', 1),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens/immunbiologie', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens', 'subtopic', '11/12', 'Immunbiologie', 'Immunobiology', 'p. 63', '{"section": "4.1.4.2"}', 2),
  ('DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens/entwicklung-des-lebens', 'DE-TH/biologie-gymnasium-2026/qualifikationsphase/vielfalt-des-lebens', 'subtopic', '11/12', 'Entwicklung des Lebens', 'Development of life', 'p. 65', '{"section": "4.1.4.3"}', 3)
) AS v(node_key, parent_key, level, grade_band, label_de, label_en, source_pages, facts, sort_order)
JOIN projects p ON p.slug = 'thuringia-curriculum-repository'
JOIN curriculum_repository_structure_nodes parent ON parent.project_id = p.id AND parent.node_key = v.parent_key
ON CONFLICT (project_id, node_key) DO NOTHING;

DO $$
DECLARE added integer; fixed integer;
BEGIN
  SELECT count(*) INTO added FROM curriculum_repository_structure_nodes WHERE origin = 'lehrplan-toc-2026-11-02';
  SELECT count(*) INTO fixed FROM curriculum_repository_structure_nodes WHERE label_de = 'Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen';
  IF added <> 16 OR fixed <> 0 THEN
    RAISE EXCEPTION 'migration 220: % table-of-contents nodes (expected 16), % nodes still carry the old heading', added, fixed;
  END IF;
END $$;
